(a) $\begin{array}{c|ccccc}t&-2&-1&0&1&2\\x&0&1&2&3&4\\y&3&0&-1&0&3\end{array}$
(b) Rearrange $x=t+2$ to get $t=x-2$.
$\begin{aligned}y&=(x-2)^2-1\end{aligned}$
Sketch the upward-opening parabola through the table points, with vertex $(2,-1)$ and intercepts $(1,0)$, $(3,0)$ and $(0,3)$. The table samples the curve; it does not restrict $t$.
[tikz]
\begin{tikzpicture}[x=9mm,y=7mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveBlue}{HTML}{268CFF}
\draw[<->,black] (-0.8,0)--(5,0) node[right] {$x$};
\draw[<->,black] (0,-1.8)--(0,5) node[above] {$y$};
\draw[thick,curveBlue,<->,domain=-0.4:4.4,samples=81] plot (\x,{(\x-2)*(\x-2)-1});
\foreach \x/\y in {0/3,1/0,2/-1,3/0,4/3}{\fill[black] (\x,\y) circle (1.3pt);}
\path (0,3) node[left] {$(0,3)$};
\path (1,0) node[below left] {$(1,0)$};
\path (3,0) node[below right] {$(3,0)$};
\path (2,-1) node[below] {$(2,-1)$};
\path (4,3) node[right] {$(4,3)$};
\end{tikzpicture}
[/tikz]

(a) $\begin{array}{c|ccccc}t&-2&-1&0&1&2\\x&-3&-2&-1&0&1\\y&-3&-1&1&3&5\end{array}$
(b) Rearrange $x=t-1$ to get $t=x+1$.
$\begin{aligned}y&=2(x+1)+1\\y&=2x+3\end{aligned}$
Each increase of $1$ in $x$ increases $y$ by $2$. Sketch the whole straight line, with gradient $2$ and $y$-intercept $3$.
[tikz]
\begin{tikzpicture}[x=10mm,y=6mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveBlue}{HTML}{268CFF}
\draw[<->,black] (-3.8,0)--(1.8,0) node[right] {$x$};
\draw[<->,black] (0,-4.5)--(0,6.5) node[above] {$y$};
\draw[thick,curveBlue,<->] (-3.6,-4.2)--(1.6,6.2);
\foreach \x/\y in {-3/-3,-2/-1,-1/1,0/3,1/5}{\fill[black] (\x,\y) circle (1.3pt);}
\path (-3,-3) node[left] {$(-3,-3)$};
\path (0,3) node[right] {$(0,3)$};
\path (1,5) node[right] {$(1,5)$};
\fill[black] (-1.5,0) circle (1.3pt);
\path (-1.5,0) node[below left] {$(-\frac32,0)$};
\end{tikzpicture}
[/tikz]

(a) $\begin{array}{c|ccc}t&0&1&2\\x&-1&0&1\\y&1&3&5\end{array}$
(b) $t=x+1$.
$\begin{aligned}y&=2(x+1)+1\\y&=2x+3\end{aligned}$
Since $0\le t\le2$, the restriction is $-1\le x\le1$. Draw only the segment from $(-1,1)$ to $(1,5)$, with both endpoints filled.
[tikz]
\begin{tikzpicture}[x=15mm,y=8mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveBlue}{HTML}{268CFF}
\draw[<->,black] (-1.8,0)--(1.8,0) node[right] {$x$};
\draw[->,black] (0,-0.5)--(0,6) node[above] {$y$};
\draw[thick,curveBlue] (-1,1)--(1,5);
\fill[black] (-1,1) circle (1.5pt);
\fill[black] (1,5) circle (1.5pt);
\fill[black] (0,3) circle (1.3pt);
\path (-1,1) node[left] {$(-1,1)$};
\path (1,5) node[right] {$(1,5)$};
\path (0,3) node[right] {$(0,3)$};
\end{tikzpicture}
[/tikz]

Rearrange the parametric equations:
$\cos t=\frac{x+2}{3},\qquad \sin t=\frac{1-y}{3}$.
Using $\cos^2t+\sin^2t=1$:
$\begin{aligned}\left(\frac{x+2}{3}\right)^2+\left(\frac{1-y}{3}\right)^2&=1\\(x+2)^2+(y-1)^2&=9\end{aligned}$
The centre is $(-2,1)$ and the radius is $3$. Over $0\le t\le2\pi$, the entire circle is traced. The negative sine coefficient reverses the direction of tracing; it does not restrict the curve to a semicircle.
[tikz]
\begin{tikzpicture}[x=7mm,y=7mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveBlue}{HTML}{268CFF}
\draw[<->,black] (-6,0)--(2,0) node[right] {$x$};
\draw[<->,black] (0,-3)--(0,5) node[above] {$y$};
\draw[thick,curveBlue] (-2,1) circle (3);
\fill[black] (-2,1) circle (1.5pt);
\path (-2,1) node[below left] {$C=(-2,1)$};
\draw[black,dashed] (-2,1)--(-2,4);
\path (-2,2.5) node[left] {$r=3$};
\fill[black] (1,1) circle (1.5pt);
\path (1,1) node[right] {$(1,1),\ t=0$};
\path (-5,1) node[left] {$(-5,1)$};
\path (-2,4) node[above] {$(-2,4)$};
\path (-2,-2) node[below] {$(-2,-2)$};
\end{tikzpicture}
[/tikz]

Rearrange the parametric equations:
$\cos t=\frac{x+2}{3},\qquad \sin t=\frac{y-1}{3}$.
Using $\cos^2t+\sin^2t=1$:
$\begin{aligned}\left(\frac{x+2}{3}\right)^2+\left(\frac{y-1}{3}\right)^2&=1\\(x+2)^2+(y-1)^2&=9\end{aligned}$
The centre is $(-2,1)$ and the radius is $3$. Since $\sin t\ge0$ throughout $0\le t\le\pi$, only the upper semicircle, $y\ge1$, is traced.
At $t=0$, the endpoint is $(1,1)$; at $t=\pi$, it is $(-5,1)$. Both endpoints are included.
[tikz]
\begin{tikzpicture}[x=8mm,y=8mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\definecolor{curveBlue}{HTML}{268CFF}
\draw[<->,black] (-6,0)--(2,0) node[right] {$x$};
\draw[->,black] (0,-0.6)--(0,5) node[above] {$y$};
\draw[thick,curveBlue] (1,1) arc[start angle=0,end angle=180,radius=3];
\fill[black] (-2,1) circle (1.3pt);
\path (-2,1) node[below] {$C=(-2,1)$};
\draw[black,dashed] (-2,1)--(-2,4);
\path (-2,2.5) node[left] {$r=3$};
\fill[black] (1,1) circle (1.5pt);
\fill[black] (-5,1) circle (1.5pt);
\path (1,1) node[right] {$(1,1)$};
\path (-5,1) node[left] {$(-5,1)$};
\path (-2,4) node[above] {$(-2,4)$};
\end{tikzpicture}
[/tikz]
